<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
requireLogin();

$uid = current_user_id();
$success = flash('success');
$stmt = db()->prepare('SELECT name, email FROM users WHERE id = ? LIMIT 1'); $stmt->bind_param('i', $uid); $stmt->execute(); $user = $stmt->get_result()->fetch_assoc(); $stmt->close();
$stmt = db()->prepare('SELECT id, profile_name, full_name, date_of_birth, time_of_birth, birth_place, location_name, latitude, longitude, timezone FROM birth_profiles WHERE user_id = ? ORDER BY id DESC LIMIT 1'); $stmt->bind_param('i', $uid); $stmt->execute(); $profile = $stmt->get_result()->fetch_assoc(); $stmt->close();
$stmt = db()->prepare('SELECT id, birth_profile_id, created_at FROM kundli_calculations WHERE user_id = ? ORDER BY id DESC LIMIT 1'); $stmt->bind_param('i', $uid); $stmt->execute(); $kundli = $stmt->get_result()->fetch_assoc(); $stmt->close();
$apiConfigured = VEDIC_API_KEY !== '';
?>
